"""Authoring source for Sol's C1 leaf records. All judgments are editorial and evidence-bounded."""

import copy
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
HERE = Path(__file__).resolve().parent
ism = json.loads((ROOT / "public/ism.json").read_text(encoding="utf-8"))
enrich = json.loads((ROOT / "public/cube-enrichments.json").read_text(encoding="utf-8"))["nodes"]
parent_nodes = {n["code"]: n for n in json.loads((HERE / "sol-tree-B.json").read_text(encoding="utf-8"))["nodes"]}
pilot = {n["code"]: n for n in json.loads((HERE.parent / "sol-categories.json").read_text(encoding="utf-8"))["categories"]}
sources = {}


def source(key, author, work, version, locator, url, supports, limits, read_scope=None):
    sources[key] = dict(author=author, work=work, version=version, locator=locator,
                        url=url, read_scope=read_scope or locator, supports=supports,
                        limits=limits, relation="editorial_partial_comparison")


for code, node in parent_nodes.items():
    for side, short in (("pro_sources", "P"), ("con_sources", "C")):
        if node[side]:
            sources[f"B:{code}:{short}"] = copy.deepcopy(node[side][0])

for code in ("1-1-1-2", "1-1-3-1", "1-1-4-4"):
    for side, short in (("pro", "P"), ("con", "C")):
        item = pilot[code]["stance_profile"]["primary_evidence"][side]
        sources[f"P:{code}:{short}"] = dict(
            author=item["author"], work=item["work"], version=item["edition_translation"],
            locator=item["locator"], url=item["url"], read_scope=item["review_scope"],
            supports=item["supports"], limits=item["limits"], relation="editorial_partial_comparison")

