records = []


def add(code, axes, portrait, problem, example, opponent, reply, tension,
        assessment, candidate, redirect, self_question, pro=None, con=None,
        purpose_gap=None):
    assert len(axes) == 4, code
    records.append(dict(code=code, axes=axes, portrait=portrait, problem=problem,
                        example=example, opponent=opponent, reply=reply,
                        tension=tension, assessment=assessment, candidate=candidate,
                        redirect=redirect, self_question=self_question,
                        pro=pro, con=con, purpose_gap=purpose_gap))


# 1-1: the fourth digit changes the envisaged end, not merely the theory of nature.
