        record["pro"] = "WILDE_AESTHETIC"
        record["purpose_gap"] = "王尔德序言已核艺术不以实用为终点的局部主张；课程经验论轴仍需其他证据"
        record["assessment"] = "王尔德序言支持艺术不以实用为唯一尺度；它不能证明课程经验论三格，也不能让作品对人的伤害免于讨论。"
